const GOAL_SQM = 125;               // الهدف بالمتر المربع
const GOAL = GOAL_SQM * PRICE_PER_SQM; // = 100.000 €
const INITIAL_COLLECTED = 0;        // المبلغ المحصّل مسبقاً (€)
const MIN_SQM = 0;                  // لا يوجد حد أدنى
const MIN_AMOUNT = 0;
const AREA_OPTIONS = [0.25, 0.5, 0.75, 1]; // الخيارات السريعة بالمتر المربع
const CENTER_NAME_AR = "التبرع لفائدة مركز جسور الإسلامي هانوفر";
const CENTER_NAME_DE = "Familienbrücken Hannover e.V.";
const API_URL = "https://script.google.com/macros/s/AKfycbyiThFLS73Vs0l8-GXaKZbIA_Lg4RD6RABp9OjOrLr_06BKqxK8SBKuD7YrLsw85j9Q/exec";
const PAYPAL_URL = "https://www.paypal.com/donate/?hosted_button_id=8LELT3CVJBCUQ";
const DATENSCHUTZ_TEXT = `Datenschutzhinweis gemäß DSGVO Art. 13:

Verantwortlicher: Familienbrücken Hannover e.V.
Zweck: Spendenabwicklung und -verwaltung
Rechtsgrundlage: Ihre Einwilligung (Art. 6 Abs. 1 lit. a DSGVO)
Speicherdauer: Bis 31. Dezember 2026, danach werden alle Daten unwiderruflich gelöscht.
Ihre Rechte: Auskunft, Berichtigung, Löschung und Widerruf der Einwilligung jederzeit möglich.
Kontakt: info@familienbruecken-hannover.de`;

const PAYMENT_OPTIONS = [
  { id: "1", label: "دفعة واحدة",    labelDe: "Einmalig",       installments: 1 },
  { id: "3", label: "3 أقساط شهرية", labelDe: "3 Monatsraten",  installments: 3 },
  { id: "6", label: "6 أقساط شهرية", labelDe: "6 Monatsraten",  installments: 6 },
  { id: "8", label: "8 أقساط شهرية", labelDe: "8 Monatsraten",  installments: 8 },
];

const LOGO_SRC = "data:image/jpeg;base64,";

function formatEuro(n) {
  return new Intl.NumberFormat("de-DE", { style: "currency", currency: "EUR", maximumFractionDigits: 0 }).format(n);
}

function formatSqm(n) {
  const num = Number(n) || 0;
  const str = new Intl.NumberFormat("de-DE", { maximumFractionDigits: 2 }).format(num);
  return `${str} m²`;
}

async function apiCall(params) {
  const url = new URL(API_URL);
  Object.entries(params).forEach(([k, v]) => url.searchParams.append(k, v));
  try {
    const res = await fetch(url.toString());
    return await res.json();
  } catch (e) { return { error: e.message }; }
}

async function loadDonations() {
  const res = await apiCall({ action: "getAll" });
  return res.donations || [];
}
async function addDonation(d)      { return await apiCall({ action: "add",     data: JSON.stringify(d) }); }
async function confirmDonationAPI(id) { return await apiCall({ action: "confirm", id }); }
async function deleteDonationAPI(id)  { return await apiCall({ action: "delete",  id }); }

