// ─── Export Excel ─────────────────────────────────────────────────────────────
function exportToExcel(donations) {
  const confirmed = donations.filter(d => d.confirmed);
  const payLabel  = id => id==="paypal" ? "PayPal" : (PAYMENT_OPTIONS.find(o=>o.id===id)?.label || id);
  const sqmOf     = d => (d.sqm != null ? Number(d.sqm) : (parseFloat(d.amount)||0)/PRICE_PER_SQM);
  const toRow = d => ({
    "الاسم":               d.name,
    "البريد الإلكتروني":   d.email,
    "رقم الهاتف":          d.phone,
    "المساحة (m²)":        sqmOf(d),
    "المبلغ (€)":          d.amount,
    "طريقة الدفع":         payLabel(d.paymentType),
    "صاحب الحساب":         d.accountHolder || "",
    "IBAN":                d.iban || "",
    "القسط الشهري (€)":    d.installments>1 ? (d.amount/d.installments).toFixed(2) : d.amount,
    "شهادة تبرع مطلوبة":   d.needsCertificate ? "نعم" : "لا",
    "الحالة":              d.confirmed ? "مؤكد" : "في الانتظار",
    "موافقة على الخصوصية": "نعم",
    "ملاحظة":              d.note||"",
    "التاريخ":             new Date(d.date).toLocaleDateString("de-DE"),
  });
  const wb   = XLSX.utils.book_new();
  const cols = [{wch:25},{wch:30},{wch:18},{wch:12},{wch:12},{wch:20},{wch:25},{wch:26},{wch:16},{wch:18},{wch:12},{wch:20},{wch:25},{wch:14}];
  const ws1  = XLSX.utils.json_to_sheet(donations.map(toRow)); ws1["!cols"]=cols;
  const ws2  = XLSX.utils.json_to_sheet(confirmed.map(toRow)); ws2["!cols"]=cols;
  // شهادات التبرع
  const certNeeded = confirmed.filter(d=>d.needsCertificate);
  const ws4 = XLSX.utils.json_to_sheet(certNeeded.map(d=>({
    "الاسم": d.name, "البريد الإلكتروني": d.email,
    "رقم الهاتف": d.phone, "المساحة (m²)": sqmOf(d), "المبلغ (€)": d.amount,
    "طريقة الدفع": payLabel(d.paymentType),
    "التاريخ": new Date(d.date).toLocaleDateString("de-DE"),
  })));
  ws4["!cols"]=[{wch:25},{wch:30},{wch:18},{wch:12},{wch:12},{wch:22},{wch:14}];
  const totalConfirmed = confirmed.reduce((s,d)=>s+parseFloat(d.amount),0);
  const soldSqm = totalConfirmed / PRICE_PER_SQM;
  const ws3 = XLSX.utils.json_to_sheet([
    { "البيان":"المركز",                          "القيمة":CENTER_NAME_AR },
    { "البيان":"Verantwortlicher",                "القيمة":CENTER_NAME_DE },
    { "البيان":"Speicherdauer",                   "القيمة":"Bis 31. Dezember 2026" },
    { "البيان":"سعر المتر المربع",                 "القيمة":formatEuro(PRICE_PER_SQM) },
    { "البيان":"إجمالي التبرعات المؤكدة",          "القيمة":formatEuro(totalConfirmed) },
    { "البيان":"المساحة المباعة (m²)",            "القيمة":soldSqm.toFixed(2) },
    { "البيان":"عدد المتبرعين المؤكدين",           "القيمة":confirmed.length },
    { "البيان":"يحتاجون شهادة تبرع",              "القيمة":certNeeded.length },
    { "البيان":"الهدف (m²)",                       "القيمة":GOAL_SQM },
    { "البيان":"الهدف (€)",                        "القيمة":formatEuro(GOAL) },
    { "البيان":"المتبقي (m²)",                     "القيمة":Math.max(GOAL_SQM-soldSqm,0).toFixed(2) },
    { "البيان":"نسبة الإنجاز",                     "القيمة":`${((soldSqm/GOAL_SQM)*100).toFixed(1)}%` },
  ]); ws3["!cols"]=[{wch:35},{wch:25}];
  XLSX.utils.book_append_sheet(wb, ws1, "جميع التبرعات");
  XLSX.utils.book_append_sheet(wb, ws2, "المؤكدة فقط");
  XLSX.utils.book_append_sheet(wb, ws3, "ملخص الحملة");
  XLSX.utils.book_append_sheet(wb, ws4, "شهادات التبرع المطلوبة");
  XLSX.writeFile(wb, `تبرعات-جسور-الإسلامي-${new Date().toISOString().slice(0,10)}.xlsx`);
}

// ─── Confetti ─────────────────────────────────────────────────────────────────
function Confetti({ trigger }) {
  const [particles, setParticles] = useState([]);
  useEffect(()=>{
    if(!trigger) return;
    const p=Array.from({length:50},(_,i)=>({ id:i, x:Math.random()*100, color:["#FFD700","#FF6B35","#4CAF50","#2196F3","#E91E63","#fff"][Math.floor(Math.random()*6)], delay:Math.random()*0.6, duration:1.5+Math.random() }));
    setParticles(p);
    const t=setTimeout(()=>setParticles([]),3000);
    return ()=>clearTimeout(t);
  },[trigger]);
  return (
    <div style={{ position:"fixed",inset:0,pointerEvents:"none",zIndex:9999 }}>
      {particles.map(p=><div key={p.id} style={{ position:"absolute",left:`${p.x}%`,top:"-20px",width:10,height:10,background:p.color,borderRadius:Math.random()>0.5?"50%":"2px",animation:`fall ${p.duration}s ${p.delay}s ease-in forwards` }}/>)}
      <style>{`@keyframes fall{to{transform:translateY(110vh) rotate(720deg);opacity:0;}}`}</style>
    </div>
  );
}

// ─── Input Field ──────────────────────────────────────────────────────────────
function InputField({ label, field, type, placeholder, value, onChange, dir="rtl", hint }) {
  const [focused, setFocused] = useState(false);
  return (
    <div style={{ marginBottom:18 }}>
      <label style={{ display:"block", color:"rgba(255,255,255,0.8)", marginBottom:4, fontSize:14, fontWeight:600 }}>{label}</label>
      {hint && <p style={{ margin:"0 0 6px", fontSize:12, color:"#FFD700" }}>ℹ️ {hint}</p>}
      <input type={type} placeholder={placeholder} value={value} dir={dir}
        onChange={e=>onChange(field,e.target.value)}
        onFocus={()=>setFocused(true)} onBlur={()=>setFocused(false)}
        style={{ width:"100%", padding:"13px 16px", borderRadius:12, border:`2px solid ${focused?"#FFD700":"rgba(255,255,255,0.15)"}`, background:"rgba(255,255,255,0.08)", color:"#fff", fontSize:16, boxSizing:"border-box", outline:"none", transition:"border-color 0.2s" }}
      />
    </div>
  );
}

// ─── Donor Form ───────────────────────────────────────────────────────────────
function DonorForm({ onSuccess }) {
  const [form, setForm] = useState({ name:"", email:"", phone:"", sqm:"1", paymentType:"1", iban:"", accountHolder:"", note:"", needsCertificate:false });
  const [consent, setConsent]             = useState(false);
  const [showDatenschutz, setShowDatenschutz] = useState(false);
  const [showSepa, setShowSepa]           = useState(false);
  const [loading, setLoading]             = useState(false);
  const [error, setError]                 = useState("");
  const [done, setDone]                   = useState(false);

  const setField = (f,v) => setForm(p=>({...p,[f]:v}));
  const selectedOption = PAYMENT_OPTIONS.find(o=>o.id===form.paymentType);
  const sqmValue = parseFloat(form.sqm);
  const amount   = !isNaN(sqmValue) ? sqmValue * PRICE_PER_SQM : 0;
  const isSepa   = true; // الخصم يتم دائماً عبر SEPA
  const monthly = selectedOption?.installments > 1 && amount
    ? (amount/selectedOption.installments).toFixed(0) : null;

  async function submit(viaPayPal = false) {
    if (!form.name.trim()||!form.email.trim()||!form.phone.trim()||!form.sqm) { setError("يرجى ملء جميع الحقول المطلوبة"); return; }
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.email)) { setError("البريد الإلكتروني غير صحيح"); return; }
    if (isNaN(sqmValue)||sqmValue<=0) { setError("يرجى اختيار أو إدخال مساحة صحيحة"); return; }
    // عند الدفع عبر PayPal لا نطلب بيانات SEPA
    if (!viaPayPal && isSepa) {
      const ibanClean = form.iban.replace(/\s+/g,"").toUpperCase();
      if (!form.accountHolder.trim()) { setShowSepa(true); setError("يرجى إدخال اسم صاحب الحساب"); return; }
      if (!/^DE\d{20}$/.test(ibanClean)) { setShowSepa(true); setError("رقم IBAN غير صحيح (مثال: DE.. مكوّن من 22 خانة)"); return; }
    }
    if (!consent) { setError("يجب الموافقة على سياسة الخصوصية للمتابعة"); return; }
    setLoading(true); setError("");
    const donation = {
      id: Date.now(), name:form.name.trim(), email:form.email.trim(), phone:form.phone.trim(),
      sqm:sqmValue, amount,
      paymentType: viaPayPal ? "paypal" : form.paymentType,
      installments: viaPayPal ? 1 : (selectedOption?.installments||1),
      iban: (!viaPayPal && isSepa) ? form.iban.replace(/\s+/g,"").toUpperCase() : "",
      accountHolder: (!viaPayPal && isSepa) ? form.accountHolder.trim() : "",
      sepaMandate: !viaPayPal && isSepa,
      needsCertificate:form.needsCertificate, note:form.note.trim(),
      date:new Date().toISOString(), confirmed:false,
    };
    const res = await addDonation(donation);
    if (res.error) { setError("خطأ في الاتصال، حاول مرة أخرى"); setLoading(false); return; }
    setLoading(false);
    onSuccess && onSuccess();
    if (viaPayPal) {
      // فتح صفحة PayPal ثم عرض شاشة الشكر
      window.open(PAYPAL_URL, "_blank", "noopener,noreferrer");
    }
    setDone(true);
  }

  if (done) return (
    <div style={{ textAlign:"center", padding:"60px 20px", color:"#fff" }}>
      <div style={{ fontSize:80, marginBottom:16 }}>🎉</div>
      <h2 style={{ fontSize:30, fontWeight:800, marginBottom:10 }}>جزاك الله خيراً!</h2>
      <p style={{ fontSize:17, opacity:0.85 }}>تم تسجيل تبرعك بنجاح</p>
      <div style={{ marginTop:20, maxWidth:520, marginLeft:"auto", marginRight:"auto", background:"rgba(255,215,0,0.08)", border:"1px solid rgba(255,215,0,0.3)", borderRadius:16, padding:"20px 24px" }}>
        <p style={{ margin:0, fontSize:16, color:"#FFD700", fontWeight:700, lineHeight:1.9 }}>
          تقبّل الله منك صدقتك وجعلها في ميزان حسناتك، سوف يتم مراسلتك خلال الأيام القليلة القادمة بشهادة التبرع وكذلك شهادة الملكية الفخرية
        </p>
      </div>
      {form.needsCertificate && (
        <div style={{ marginTop:16, background:"rgba(255,215,0,0.1)", border:"1px solid rgba(255,215,0,0.3)", borderRadius:12, padding:"12px 20px", fontSize:14, color:"#FFD700" }}>
          📧 سيتم إرسال شهادة التبرع إلى بريدك الإلكتروني
        </div>
      )}
      <div style={{ marginTop:16, background:"rgba(255,255,255,0.05)", borderRadius:14, padding:"14px 20px", border:"1px solid rgba(255,255,255,0.1)", fontSize:12, color:"rgba(255,255,255,0.45)", direction:"ltr", textAlign:"left" }}>
        🔒 Ihre Daten werden gemäß DSGVO bis 31.12.2026 gespeichert.
      </div>
      <button onClick={()=>{ setDone(false); setConsent(false); setForm({name:"",email:"",phone:"",sqm:"1",paymentType:"1",iban:"",accountHolder:"",note:"",needsCertificate:false}); }}
        style={{ marginTop:24, padding:"12px 32px", borderRadius:50, border:"none", background:"#FFD700", color:"#1a1a2e", fontWeight:700, fontSize:16, cursor:"pointer" }}>
        تبرع مرة أخرى
      </button>
    </div>
  );

  return (
    <div style={{ maxWidth:480, margin:"0 auto", padding:"24px 16px" }}>
      {showDatenschutz && <DatenschutzModal onClose={()=>setShowDatenschutz(false)} />}
      <div style={{ marginBottom:28 }}><LogoHeader size="md" /></div>

      {/* اختيار المساحة */}
      <div style={{ marginBottom:18 }}>
        <label style={{ display:"block", color:"rgba(255,255,255,0.8)", marginBottom:4, fontSize:14, fontWeight:600 }}>المساحة المراد التبرع بها *</label>
        <p style={{ margin:"0 0 10px", fontSize:12, color:"#FFD700" }}>ℹ️ سعر المتر المربع: {formatEuro(PRICE_PER_SQM)} — الهدف: {formatSqm(GOAL_SQM)}</p>
        <div style={{ display:"grid", gridTemplateColumns:"repeat(4,1fr)", gap:8, marginBottom:10 }}>
          {AREA_OPTIONS.map(opt => {
            const active = parseFloat(form.sqm)===opt;
            return (
              <button key={opt} onClick={()=>setField("sqm",String(opt))}
                style={{ padding:"14px 4px", borderRadius:12, border:`2px solid ${active?"#FFD700":"rgba(255,255,255,0.15)"}`, background:active?"rgba(255,215,0,0.12)":"rgba(255,255,255,0.04)", color:active?"#FFD700":"rgba(255,255,255,0.8)", fontWeight:800, cursor:"pointer", transition:"all 0.2s", display:"flex", flexDirection:"column", alignItems:"center", gap:3 }}>
                <span style={{ fontSize:18 }}>{formatSqm(opt)}</span>
                <span style={{ fontSize:12, opacity:0.7, fontWeight:600 }}>{formatEuro(opt*PRICE_PER_SQM)}</span>
              </button>
            );
          })}
        </div>
        {/* حقل حر لإدخال مساحة مخصصة */}
        <div>
          <label style={{ display:"block", color:"rgba(255,255,255,0.6)", marginBottom:4, fontSize:13 }}>أو أدخل مساحة مخصصة (m²)</label>
          <input type="number" min="0" step="0.25" placeholder="مثال: 1.5" value={form.sqm} dir="ltr"
            onKeyDown={e=>{ if(e.key==="-"||e.key==="e"||e.key==="+") e.preventDefault(); }}
            onChange={e=>{ const v=e.target.value; if(v===""||parseFloat(v)>=0) setField("sqm",v); }}
            style={{ width:"100%", padding:"13px 16px", borderRadius:12, border:"2px solid rgba(255,255,255,0.15)", background:"rgba(255,255,255,0.08)", color:"#fff", fontSize:16, boxSizing:"border-box", outline:"none" }} />
        </div>
        {amount > 0 && (
          <p style={{ marginTop:10, color:"#FFD700", fontSize:15, textAlign:"center", background:"rgba(255,215,0,0.08)", borderRadius:8, padding:"10px" }}>
            {formatSqm(sqmValue)} = <strong>{formatEuro(amount)}</strong>
          </p>
        )}
      </div>

      {/* طريقة الدفع */}
      <div style={{ marginBottom:18 }}>
        <label style={{ display:"block", color:"rgba(255,255,255,0.8)", marginBottom:6, fontSize:14, fontWeight:600 }}>طريقة الدفع *</label>
        <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
          {PAYMENT_OPTIONS.map(opt => (
            <button key={opt.id} onClick={()=>setField("paymentType",opt.id)}
              style={{ padding:"12px 16px", borderRadius:12, border:`2px solid ${form.paymentType===opt.id?"#FFD700":"rgba(255,255,255,0.15)"}`, background:form.paymentType===opt.id?"rgba(255,215,0,0.12)":"rgba(255,255,255,0.04)", color:form.paymentType===opt.id?"#FFD700":"rgba(255,255,255,0.75)", fontWeight:700, cursor:"pointer", fontSize:15, textAlign:"right", display:"flex", justifyContent:"space-between", alignItems:"center", transition:"all 0.2s" }}>
              <span>{opt.label}</span>
              <span style={{ fontSize:12, opacity:0.6, fontWeight:400 }}>{opt.labelDe}</span>
            </button>
          ))}
        </div>
        {monthly && (
          <p style={{ marginTop:10, color:"#FFD700", fontSize:14, textAlign:"center", background:"rgba(255,215,0,0.08)", borderRadius:8, padding:"8px" }}>
            ≈ {formatEuro(monthly)} شهرياً لمدة {selectedOption.installments} أشهر
          </p>
        )}
      </div>

      {/* المعطيات الشخصية */}
      <div style={{ marginBottom:18 }}>
        <label style={{ display:"block", color:"rgba(255,255,255,0.8)", marginBottom:10, fontSize:14, fontWeight:600 }}>المعطيات الشخصية</label>
        <InputField label="الاسم الكامل *"          field="name"   type="text"  placeholder="أدخل اسمك الكامل"  value={form.name}  onChange={setField} />
        <InputField label="البريد الإلكتروني *"      field="email"  type="email" placeholder="name@example.com"  value={form.email} onChange={setField} dir="ltr" />
        <InputField label="رقم الهاتف *"             field="phone"  type="tel"   placeholder="+49 ..."           value={form.phone} onChange={setField} dir="ltr" />
      </div>

      {/* زر PayPal */}
      <div style={{ marginBottom:18 }}>
        <button onClick={()=>submit(true)} disabled={loading||!consent}
          style={{ display:"flex", alignItems:"center", justifyContent:"center", gap:10, width:"100%", padding:"15px", borderRadius:14, border:"none", background:!consent?"rgba(0,112,186,0.4)":"#0070BA", color:"#fff", fontWeight:800, fontSize:17, cursor:!consent||loading?"not-allowed":"pointer", boxSizing:"border-box" }}>
          <span style={{ fontWeight:900, fontStyle:"italic", fontSize:19 }}>PayPal</span>
          <span>{loading ? "جارٍ التسجيل..." : "التبرع عبر PayPal"}</span>
        </button>
        <p style={{ textAlign:"center", color:"rgba(255,255,255,0.35)", fontSize:12, marginTop:8 }}>
          سيتم تسجيل بياناتك ثم تحويلك إلى صفحة PayPal الآمنة في نافذة جديدة
        </p>
      </div>

      {/* زر SEPA قابل للفتح */}
      {isSepa && (
        <div style={{ marginBottom:18 }}>
          <button onClick={()=>setShowSepa(v=>!v)}
            style={{ display:"flex", alignItems:"center", justifyContent:"center", gap:10, width:"100%", padding:"15px", borderRadius:14, border:"none", background:"#217346", color:"#fff", fontWeight:800, fontSize:17, cursor:"pointer", boxSizing:"border-box" }}>
            <span style={{ fontSize:19 }}>🏦</span>
            <span>التبرع عبر SEPA-Lastschrift</span>
            <span style={{ fontSize:14, transition:"transform 0.2s", transform:showSepa?"rotate(180deg)":"none" }}>▼</span>
          </button>
          {showSepa && (
            <div style={{ background:"rgba(33,115,70,0.08)", border:"1px solid rgba(33,115,70,0.35)", borderTop:"none", borderRadius:"0 0 14px 14px", padding:"16px", marginTop:-6 }}>
              <InputField label="اسم صاحب الحساب *" field="accountHolder" type="text" placeholder="Kontoinhaber" value={form.accountHolder} onChange={setField} />
              <InputField label="رقم الحساب الدولي IBAN *" field="iban" type="text" placeholder="DE00 0000 0000 0000 0000 00" value={form.iban} onChange={setField} dir="ltr" />
              <p style={{ margin:"4px 0 0", color:"rgba(255,255,255,0.5)", fontSize:12, lineHeight:1.6, direction:"rtl" }}>
                بتأكيدك، تمنح <strong>{CENTER_NAME_DE}</strong> تفويضاً بالخصم المباشر (SEPA-Lastschriftmandat) لسحب المبلغ
                {selectedOption?.installments>1 ? " على دفعات شهرية" : ""} من حسابك.
              </p>
            </div>
          )}
        </div>
      )}

      {/* شهادة التبرع */}
      <div style={{ background:"rgba(255,255,255,0.04)", border:"1px solid rgba(255,255,255,0.12)", borderRadius:14, padding:"14px 16px", marginBottom:18 }}>
        <div style={{ display:"flex", gap:12, alignItems:"flex-start" }}>
          <div onClick={()=>setField("needsCertificate",!form.needsCertificate)}
            style={{ width:22, height:22, minWidth:22, borderRadius:6, border:`2px solid ${form.needsCertificate?"#FFD700":"rgba(255,255,255,0.4)"}`, background:form.needsCertificate?"#FFD700":"transparent", cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center", marginTop:2, transition:"all 0.2s" }}>
            {form.needsCertificate && <span style={{ color:"#1a1a2e", fontSize:14, fontWeight:900 }}>✓</span>}
          </div>
          <div>
            <p style={{ margin:"0 0 4px", color:"rgba(255,255,255,0.85)", fontSize:14, fontWeight:600 }}>
              هل تحتاج إلى شهادة تبرع؟
            </p>
            <p style={{ margin:0, color:"rgba(255,255,255,0.5)", fontSize:12, lineHeight:1.5 }}>
              يمكنك استخدام شهادة التبرع لاسترداد المبلغ من ضرائبك السنوية في ألمانيا.
              سنرسلها إلى بريدك الإلكتروني.
              {" "}<strong style={{ color:"rgba(255,215,0,0.7)" }}>(Spendenquittung für das Finanzamt)</strong>
            </p>
          </div>
        </div>
      </div>

      {/* ملاحظة */}
      <div style={{ marginBottom:20 }}>
        <label style={{ display:"block", color:"rgba(255,255,255,0.8)", marginBottom:6, fontSize:14, fontWeight:600 }}>ملاحظة (اختياري)</label>
        <textarea placeholder="أي تفاصيل إضافية..." value={form.note} onChange={e=>setField("note",e.target.value)}
          style={{ width:"100%", padding:"12px 16px", borderRadius:12, border:"2px solid rgba(255,255,255,0.15)", background:"rgba(255,255,255,0.08)", color:"#fff", fontSize:15, resize:"none", height:70, boxSizing:"border-box", outline:"none" }} />
      </div>

      {/* موافقة الخصوصية */}
      <div style={{ background:"rgba(255,215,0,0.06)", border:`2px solid ${consent?"rgba(255,215,0,0.5)":"rgba(255,107,53,0.4)"}`, borderRadius:14, padding:"16px", marginBottom:20 }}>
        <div style={{ display:"flex", gap:12, alignItems:"flex-start" }}>
          <div onClick={()=>setConsent(v=>!v)}
            style={{ width:22, height:22, minWidth:22, borderRadius:6, border:`2px solid ${consent?"#FFD700":"rgba(255,255,255,0.4)"}`, background:consent?"#FFD700":"transparent", cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center", marginTop:2, transition:"all 0.2s" }}>
            {consent && <span style={{ color:"#1a1a2e", fontSize:14, fontWeight:900 }}>✓</span>}
          </div>
          <p style={{ margin:0, color:"rgba(255,255,255,0.8)", fontSize:13, lineHeight:1.6, direction:"rtl" }}>
            أوافق على أن يقوم <strong>Familienbrücken Hannover e.V.</strong> بحفظ بياناتي الشخصية لأغراض إدارة التبرعات فقط، وحذفها بشكل نهائي في <strong>31 ديسمبر 2026</strong>.{" "}
            <span onClick={()=>setShowDatenschutz(true)} style={{ color:"#FFD700", cursor:"pointer", textDecoration:"underline" }}>Datenschutzerklärung lesen</span>
          </p>
        </div>
        {!consent && <p style={{ margin:"10px 0 0", color:"#FF6B35", fontSize:12, textAlign:"center" }}>⚠️ الموافقة على سياسة الخصوصية إلزامية</p>}
      </div>

      {error && <p style={{ color:"#ff6b6b", marginBottom:12, textAlign:"center", fontSize:14 }}>{error}</p>}

      <button onClick={submit} disabled={loading||!consent}
        style={{ width:"100%", padding:"16px", borderRadius:14, border:"none", background:!consent?"rgba(255,255,255,0.1)":loading?"rgba(255,215,0,0.4)":"linear-gradient(135deg,#FFD700,#FF8C00)", color:!consent?"rgba(255,255,255,0.3)":"#1a1a2e", fontWeight:900, fontSize:18, cursor:!consent||loading?"not-allowed":"pointer", transition:"all 0.3s" }}>
        {loading ? "جارٍ التسجيل..." : `تأكيد التبرع بـ ${sqmValue>0 ? `${formatSqm(sqmValue)} (${formatEuro(amount)})` : "..."}`}
      </button>
      <p style={{ textAlign:"center", color:"rgba(255,255,255,0.3)", fontSize:11, marginTop:12, direction:"ltr" }}>
        🔒 Daten werden gemäß DSGVO bis 31.12.2026 gespeichert — {CENTER_NAME_DE}
      </p>
    </div>
  );
}

// ─── Display Screen ───────────────────────────────────────────────────────────
function DisplayScreen({ donations, total, confettiKey, appUrl }) {
  const [showQR, setShowQR] = useState(false);
  const collected       = INITIAL_COLLECTED + total;
  const soldSqm         = collected / PRICE_PER_SQM;
  const pct             = Math.min((soldSqm/GOAL_SQM)*100, 100);
  const remainingSqm    = Math.max(GOAL_SQM - soldSqm, 0);
  const recentConfirmed = donations.filter(d=>d.confirmed).slice(-3).reverse();
  const sqmOf           = d => (d.sqm != null ? Number(d.sqm) : (parseFloat(d.amount)||0)/PRICE_PER_SQM);

  return (
    <div style={{ position:"relative", minHeight:"100vh", background:"linear-gradient(160deg,#0d1b3e 0%,#1a1a2e 50%,#0d2818 100%)", display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center", padding:"32px 24px", fontFamily:"'Segoe UI',Tahoma,sans-serif", direction:"rtl" }}>
      <Confetti trigger={confettiKey} />
      <button onClick={()=>setShowQR(v=>!v)} style={{ position:"absolute", top:20, left:20, background:"rgba(255,215,0,0.15)", border:"1px solid rgba(255,215,0,0.4)", borderRadius:12, padding:"8px 16px", color:"#FFD700", cursor:"pointer", fontSize:14, fontWeight:700, zIndex:10 }}>
        {showQR?"✕ إخفاء QR":"📱 عرض QR"}
      </button>
      {showQR && (
        <div style={{ position:"absolute", top:70, left:20, background:"rgba(13,27,62,0.97)", border:"1px solid rgba(255,215,0,0.3)", borderRadius:20, padding:24, zIndex:20 }}>
          <p style={{ color:"#FFD700", fontWeight:700, marginBottom:12, fontSize:15, textAlign:"center" }}>📱 امسح للتبرع</p>
          <QRDisplay url={appUrl} />
        </div>
      )}
      {/* شعار الجمعية أعلى اليمين */}
      <div style={{ position:"absolute", top:20, right:20, background:"#fff", borderRadius:14, padding:"8px 12px", boxShadow:"0 4px 20px rgba(0,0,0,0.3)", zIndex:10 }}>
        <img src={LOGO_SRC} alt="Familienbrücken Hannover e.V." style={{ height:54, width:"auto", display:"block" }} />
      </div>
      {/* صورة المركز الإسلامي */}
      <div style={{ marginBottom:18, borderRadius:18, overflow:"hidden", border:"2px solid rgba(255,255,255,0.15)", boxShadow:"0 8px 30px rgba(0,0,0,0.4)", maxWidth:180 }}>
        <img src={centerImg} alt="المركز الإسلامي" style={{ width:"100%", height:"auto", display:"block" }} />
      </div>
      {/* عنوان المركز */}
      <div style={{ textAlign:"center", marginBottom:16 }}>
        <h1 style={{ margin:0, fontSize:"clamp(20px,3vw,30px)", fontWeight:900, color:"#fff", lineHeight:1.2 }}>{CENTER_NAME_AR}</h1>
        <p style={{ margin:"4px 0 0", fontSize:14, color:"rgba(255,255,255,0.5)", fontStyle:"italic" }}>{CENTER_NAME_DE}</p>
      </div>
      {/* لوحة الحديث (صورة) */}
      <div style={{ marginBottom:24, borderRadius:14, overflow:"hidden", maxWidth:520, width:"100%", boxShadow:"0 4px 20px rgba(0,0,0,0.3)" }}>
        <img src={hadithImg} alt="حديث شريف" style={{ width:"100%", height:"auto", display:"block" }} />
      </div>
      {/* رقم المساحة */}
      <div style={{ textAlign:"center", marginBottom:24 }}>
        <div style={{ fontSize:"clamp(52px,8vw,100px)", fontWeight:900, color:"#FFD700", lineHeight:1, textShadow:"0 0 60px rgba(255,215,0,0.5)" }}>{formatSqm(soldSqm)}</div>
        <div style={{ color:"rgba(255,255,255,0.45)", fontSize:20, marginTop:6 }}>من أصل {formatSqm(GOAL_SQM)} — {formatEuro(collected)}</div>
      </div>
      <div style={{ width:"100%", maxWidth:820, marginBottom:14 }}>
        <div style={{ background:"rgba(255,255,255,0.1)", borderRadius:50, height:30, overflow:"hidden" }}>
          <div style={{ width:`${pct}%`, height:"100%", background:"linear-gradient(90deg,#FFD700,#FF8C00)", borderRadius:50, transition:"width 1.5s cubic-bezier(.4,0,.2,1)", boxShadow:"0 0 20px rgba(255,165,0,0.6)", display:"flex", alignItems:"center", justifyContent:"flex-end" }}>
            <span style={{ color:"#1a1a2e", fontWeight:800, fontSize:15, paddingRight:14 }}>{pct.toFixed(1)}%</span>
          </div>
        </div>
      </div>
      {/* شبكة الأمتار المربعة — كل مربع = 1 m² */}
      <div style={{ width:"100%", maxWidth:820, marginBottom:28, display:"grid", gridTemplateColumns:"repeat(25,1fr)", gap:4 }}>
        {Array.from({length:GOAL_SQM}, (_,i) => {
          const filled = i < Math.floor(soldSqm);
          const partial = !filled && i < soldSqm;
          return (
            <div key={i} title={`${i+1} m²`} style={{ aspectRatio:"1", borderRadius:3, background: filled ? "linear-gradient(135deg,#FFD700,#FF8C00)" : partial ? "rgba(255,215,0,0.45)" : "rgba(255,255,255,0.07)", border:"1px solid rgba(255,255,255,0.08)", boxShadow: filled ? "0 0 6px rgba(255,165,0,0.5)" : "none", transition:"all 0.5s" }} />
          );
        })}
      </div>
      <div style={{ display:"grid", gridTemplateColumns:"repeat(3,1fr)", gap:16, width:"100%", maxWidth:820, marginBottom:32 }}>
        {[
          { label:"المتبرعون", value:donations.filter(d=>d.confirmed).length, icon:"👥" },
          { label:"متبقي للهدف", value:formatSqm(remainingSqm), icon:"🎯" },
          { label:"آخر تبرع", value:donations.filter(d=>d.confirmed).length?formatSqm(sqmOf(donations.filter(d=>d.confirmed).slice(-1)[0])):"—", icon:"⭐" },
        ].map(({label,value,icon})=>(
          <div key={label} style={{ background:"rgba(255,255,255,0.07)", borderRadius:20, padding:"18px 12px", textAlign:"center", border:"1px solid rgba(255,255,255,0.1)" }}>
            <div style={{ fontSize:28, marginBottom:6 }}>{icon}</div>
            <div style={{ fontSize:"clamp(18px,2.5vw,28px)", fontWeight:800, color:"#FFD700" }}>{value}</div>
            <div style={{ color:"rgba(255,255,255,0.5)", fontSize:13, marginTop:4 }}>{label}</div>
          </div>
        ))}
      </div>
      {recentConfirmed.length>0 && (
        <div style={{ width:"100%", maxWidth:820 }}>
          <h3 style={{ color:"rgba(255,255,255,0.4)", fontSize:13, marginBottom:10, textAlign:"center", letterSpacing:3 }}>آخر التبرعات</h3>
          {recentConfirmed.map((d,i)=>(
            <div key={d.id} style={{ display:"flex", justifyContent:"space-between", alignItems:"center", background:i===0?"rgba(255,215,0,0.1)":"rgba(255,255,255,0.04)", borderRadius:12, padding:"12px 20px", marginBottom:8, border:i===0?"1px solid rgba(255,215,0,0.3)":"1px solid rgba(255,255,255,0.06)", animation:i===0?"slideIn 0.5s ease":"none" }}>
              <span style={{ color:"rgba(255,255,255,0.65)", fontSize:15 }}>
                {d.paymentType==="paypal" ? "PayPal" : (PAYMENT_OPTIONS.find(o=>o.id===d.paymentType)?.label || "دفعة واحدة")} • متبرع كريم
              </span>
              <span style={{ color:"#FFD700", fontWeight:800, fontSize:20 }}>{formatSqm(sqmOf(d))}</span>
            </div>
          ))}
        </div>
      )}
      <style>{`@keyframes slideIn{from{opacity:0;transform:translateY(-10px);}to{opacity:1;transform:translateY(0);}}`}</style>
    </div>
  );
}

// ─── Admin Panel ──────────────────────────────────────────────────────────────
function AdminPanel({ donations, onConfirm, onDelete, onRefresh, appUrl, loading }) {
  const [showQRModal, setShowQRModal] = useState(false);
  const pending   = donations.filter(d=>!d.confirmed);
  const confirmed = donations.filter(d=>d.confirmed);
  const total     = confirmed.reduce((s,d)=>s+parseFloat(d.amount),0);
  const certCount = confirmed.filter(d=>d.needsCertificate).length;
  const sqmOf     = d => (d.sqm != null ? Number(d.sqm) : (parseFloat(d.amount)||0)/PRICE_PER_SQM);
  const soldSqm   = total / PRICE_PER_SQM;

  return (
    <div style={{ minHeight:"100vh", background:"#0f172a", color:"#fff", padding:"24px 16px", fontFamily:"'Segoe UI',Tahoma,sans-serif", direction:"rtl" }}>
      <div style={{ maxWidth:800, margin:"0 auto" }}>
        <div style={{ display:"flex", alignItems:"center", gap:16, marginBottom:20, flexWrap:"wrap" }}>
          <div style={{ background:"#fff", borderRadius:12, padding:"6px 12px" }}>
            <img src={LOGO_SRC} alt="Logo" style={{ height:44, width:"auto", display:"block" }} />
          </div>
          <div style={{ flex:1 }}>
            <h1 style={{ fontSize:20, fontWeight:900, margin:0 }}>🛡️ لوحة التحكم</h1>
            <p style={{ margin:0, fontSize:12, color:"rgba(255,255,255,0.4)" }}>{CENTER_NAME_AR}</p>
          </div>
          <div style={{ display:"flex", gap:8, flexWrap:"wrap" }}>
            <button onClick={onRefresh} disabled={loading} style={{ padding:"8px 14px", borderRadius:50, border:"1px solid rgba(255,255,255,0.2)", background:"transparent", color:"#fff", cursor:"pointer", fontSize:13 }}>{loading?"⏳":"🔄"}</button>
            <button onClick={()=>setShowQRModal(true)} style={{ padding:"8px 14px", borderRadius:50, border:"1px solid rgba(255,215,0,0.4)", background:"rgba(255,215,0,0.1)", color:"#FFD700", cursor:"pointer", fontSize:13, fontWeight:700 }}>📱 QR</button>
            <button onClick={()=>exportToExcel(donations)} style={{ padding:"8px 14px", borderRadius:50, border:"none", background:"linear-gradient(135deg,#217346,#2e9c5f)", color:"#fff", cursor:"pointer", fontSize:13, fontWeight:700 }}>📊 Excel</button>
          </div>
        </div>

        <div style={{ background:"rgba(33,115,70,0.1)", border:"1px solid rgba(33,115,70,0.3)", borderRadius:12, padding:"10px 16px", marginBottom:20, direction:"ltr", fontSize:12, color:"rgba(255,255,255,0.6)" }}>
          🔒 <strong>DSGVO:</strong> Alle Daten werden bis 31.12.2026 gespeichert. Verantwortlicher: {CENTER_NAME_DE}
        </div>

        <div style={{ display:"grid", gridTemplateColumns:"repeat(2,1fr)", gap:12, marginBottom:24 }}>
          <div style={{ background:"rgba(255,215,0,0.07)", border:"1px solid rgba(255,215,0,0.2)", borderRadius:16, padding:"16px", display:"grid", gridTemplateColumns:"repeat(2,1fr)", gap:12, textAlign:"center", gridColumn:"span 2" }}>
            {[
              { label:"مؤكد (هذا اللقاء)", value:formatEuro(total), color:"#FFD700" },
              { label:"المساحة المباعة",    value:formatSqm(soldSqm),  color:"#FFD700" },
              { label:"متبرعون مؤكدون",   value:confirmed.length,    color:"#4CAF50" },
              { label:"في الانتظار",       value:pending.length,      color:"#FF6B35" },
              { label:"يحتاجون شهادة",    value:certCount,            color:"#2196F3" },
            ].map(({label,value,color})=>(
              <div key={label}>
                <div style={{ fontSize:20, fontWeight:800, color }}>{value}</div>
                <div style={{ fontSize:11, color:"rgba(255,255,255,0.45)", marginTop:2 }}>{label}</div>
              </div>
            ))}
          </div>
        </div>

        {pending.length>0 && (
          <div style={{ marginBottom:28 }}>
            <h2 style={{ color:"#FF6B35", fontSize:15, marginBottom:12 }}>⏳ بانتظار التأكيد ({pending.length})</h2>
            {pending.map(d=>(
              <div key={d.id} style={{ background:"rgba(255,107,53,0.1)", border:"1px solid rgba(255,107,53,0.3)", borderRadius:14, padding:"14px 16px", marginBottom:10 }}>
                <div style={{ display:"flex", justifyContent:"space-between", flexWrap:"wrap", gap:8 }}>
                  <div>
                    <p style={{ margin:"0 0 2px", fontWeight:700, fontSize:15 }}>{d.name}</p>
                    <p style={{ margin:"0 0 2px", color:"rgba(255,255,255,0.5)", fontSize:12 }}>{d.email}</p>
                    <p style={{ margin:"0 0 2px", color:"rgba(255,255,255,0.5)", fontSize:12 }}>{d.phone}</p>
                    <p style={{ margin:0, fontSize:12, color:"rgba(255,255,255,0.35)" }}>
                      {d.paymentType==="paypal" ? "PayPal" : (PAYMENT_OPTIONS.find(o=>o.id===d.paymentType)?.label||"دفعة واحدة")}
                      {d.sepaMandate&&d.iban&&` • 🏦 ${d.accountHolder||""} (${d.iban})`}
                      {d.needsCertificate&&" • 📄 يحتاج شهادة تبرع"}
                      {d.note&&` • ${d.note}`}
                    </p>
                  </div>
                  <div style={{ textAlign:"left" }}>
                    <p style={{ color:"#FFD700", fontWeight:800, fontSize:22, margin:"0 0 2px" }}>{formatSqm(sqmOf(d))}</p>
                    <p style={{ color:"rgba(255,215,0,0.6)", fontSize:13, margin:"0 0 8px" }}>{formatEuro(d.amount)}</p>
                    <div style={{ display:"flex", gap:8 }}>
                      <button onClick={()=>onConfirm(d.id)} style={{ padding:"7px 18px", borderRadius:8, border:"none", background:"#4CAF50", color:"#fff", fontWeight:700, cursor:"pointer", fontSize:13 }}>✓ تأكيد</button>
                      <button onClick={()=>onDelete(d.id)}  style={{ padding:"7px 14px", borderRadius:8, border:"none", background:"rgba(255,255,255,0.08)", color:"#fff", cursor:"pointer", fontSize:13 }}>✕</button>
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}

        <div>
          <h2 style={{ color:"#4CAF50", fontSize:15, marginBottom:12 }}>✅ مؤكدة ({confirmed.length})</h2>
          {confirmed.length===0 && <p style={{ color:"rgba(255,255,255,0.3)", fontSize:14 }}>لا توجد تبرعات مؤكدة بعد</p>}
          {confirmed.slice().reverse().map(d=>(
            <div key={d.id} style={{ background:"rgba(76,175,80,0.06)", border:"1px solid rgba(76,175,80,0.18)", borderRadius:12, padding:"11px 16px", marginBottom:8, display:"flex", justifyContent:"space-between", alignItems:"center", flexWrap:"wrap", gap:8 }}>
              <div>
                <span style={{ fontWeight:700 }}>{d.name}</span>
                <span style={{ color:"rgba(255,255,255,0.35)", fontSize:12, marginRight:8 }}>{d.email}</span>
                {d.needsCertificate && <span style={{ color:"#2196F3", fontSize:12 }}>• 📄</span>}
                {d.installments>1 && <span style={{ color:"rgba(255,255,255,0.4)", fontSize:12 }}>• {d.installments} أقساط</span>}
                {d.sepaMandate && <span style={{ color:"#4CAF50", fontSize:12 }}>• 🏦 SEPA</span>}
              </div>
              <div style={{ display:"flex", alignItems:"center", gap:12 }}>
                <span style={{ color:"#4CAF50", fontWeight:700 }}>{formatSqm(sqmOf(d))}</span>
                <span style={{ color:"rgba(255,255,255,0.4)", fontSize:13 }}>{formatEuro(d.amount)}</span>
                <button onClick={()=>onDelete(d.id)} style={{ background:"none", border:"none", color:"rgba(255,255,255,0.2)", cursor:"pointer", fontSize:16 }}>✕</button>
              </div>
            </div>
          ))}
        </div>
      </div>

      {showQRModal && (
        <div style={{ position:"fixed", inset:0, background:"rgba(0,0,0,0.85)", display:"flex", alignItems:"center", justifyContent:"center", zIndex:200 }} onClick={()=>setShowQRModal(false)}>
          <div style={{ background:"#0f172a", borderRadius:24, padding:36, border:"1px solid rgba(255,215,0,0.3)", maxWidth:340, width:"90%", textAlign:"center" }} onClick={e=>e.stopPropagation()}>
            <div style={{ background:"#fff", borderRadius:12, padding:"8px 14px", display:"inline-block", marginBottom:16 }}>
              <img src={LOGO_SRC} alt="Logo" style={{ height:50, width:"auto" }} />
            </div>
            <h2 style={{ color:"#FFD700", marginBottom:4, fontSize:18 }}>📱 QR Code للتبرع</h2>
            <p style={{ color:"rgba(255,255,255,0.45)", fontSize:13, marginBottom:20 }}>شارك مع الحضور ليتبرعوا مباشرة</p>
            <QRDisplay url={appUrl} />
            <button onClick={()=>setShowQRModal(false)} style={{ marginTop:22, padding:"10px 32px", borderRadius:50, border:"none", background:"rgba(255,255,255,0.08)", color:"#fff", cursor:"pointer" }}>إغلاق</button>
          </div>
        </div>
      )}
    </div>
  );
}

// ─── Main App ─────────────────────────────────────────────────────────────────
export default function App() {
  const [view, setView]                   = useState("form");
  const [adminPass, setAdminPass]         = useState("");
  const [showAdminLogin, setShowAdminLogin] = useState(false);
  const [donations, setDonations]         = useState([]);
  const [confettiKey, setConfettiKey]     = useState(0);
  const [loading, setLoading]             = useState(false);
  const PASS   = "admin123";
  const appUrl = "https://islamisches-zentrum.vercel.app/";
  const total  = donations.filter(d=>d.confirmed).reduce((s,d)=>s+parseFloat(d.amount),0);

  const refresh = useCallback(async()=>{
    setLoading(true);
    const data = await loadDonations();
    setDonations(data);
    setLoading(false);
  },[]);

  useEffect(()=>{ refresh(); },[refresh]);
  useEffect(()=>{
    if(view==="display"||view==="admin"){ const iv=setInterval(refresh,5000); return ()=>clearInterval(iv); }
  },[view,refresh]);

  async function confirmDonation(id){ await confirmDonationAPI(id); await refresh(); setConfettiKey(k=>k+1); }
  async function deleteDonation(id) { await deleteDonationAPI(id);  await refresh(); }

  const Nav=()=>(
    <div style={{ position:"fixed", bottom:0, left:0, right:0, background:"rgba(10,10,30,0.97)", backdropFilter:"blur(10px)", borderTop:"1px solid rgba(255,255,255,0.15)", display:"flex", zIndex:100 }}>
      {[{id:"form",label:"تبرع",icon:"💛"},{id:"display",label:"الشاشة",icon:"📺"}].map(v=>(
        <button key={v.id} onClick={()=>{ setShowAdminLogin(false); setView(v.id); }}
          style={{ flex:1, padding:"13px 0", border:"none", background:"transparent", color:view===v.id?"#FFD700":"#ffffff", fontWeight:700, fontSize:13, cursor:"pointer", borderTop:view===v.id?"2px solid #FFD700":"2px solid transparent", display:"flex", flexDirection:"column", alignItems:"center", gap:2 }}>
          <span style={{ fontSize:20 }}>{v.icon}</span>{v.label}
        </button>
      ))}
      <button onClick={()=>{ if(view==="admin"){ setView("form"); } else if(showAdminLogin){ setShowAdminLogin(false); } else { setShowAdminLogin(true); } }}
        style={{ flex:1, padding:"13px 0", border:"none", background:"transparent", color:view==="admin"?"#FFD700":"#ffffff", fontWeight:700, fontSize:13, cursor:"pointer", borderTop:view==="admin"?"2px solid #FFD700":"2px solid transparent", display:"flex", flexDirection:"column", alignItems:"center", gap:2 }}>
        <span style={{ fontSize:20 }}>🛡️</span>إدارة
      </button>
    </div>
  );

  if(showAdminLogin) return (
    <div style={{ minHeight:"100vh", background:"#0f172a", display:"flex", alignItems:"center", justifyContent:"center", direction:"rtl", paddingBottom:70 }}>
      <div style={{ background:"rgba(255,255,255,0.05)", borderRadius:20, padding:32, width:300, border:"1px solid rgba(255,255,255,0.1)", textAlign:"center" }}>
        <div style={{ background:"#fff", borderRadius:12, padding:"8px 16px", display:"inline-block", marginBottom:16 }}>
          <img src={LOGO_SRC} alt="Logo" style={{ height:50, width:"auto" }} />
        </div>
        <h2 style={{ color:"#fff", marginBottom:20, fontSize:18 }}>🔐 دخول الإدارة</h2>
        <input type="password" placeholder="كلمة المرور" value={adminPass} onChange={e=>setAdminPass(e.target.value)}
          onKeyDown={e=>e.key==="Enter"&&(adminPass===PASS?(setShowAdminLogin(false),setView("admin")):alert("كلمة مرور خاطئة"))}
          style={{ width:"100%", padding:"12px 16px", borderRadius:10, border:"2px solid rgba(255,255,255,0.15)", background:"rgba(255,255,255,0.08)", color:"#fff", fontSize:16, boxSizing:"border-box", marginBottom:14, outline:"none" }} />
        <button onClick={()=>{ if(adminPass===PASS){setShowAdminLogin(false);setView("admin");}else alert("كلمة مرور خاطئة"); }}
          style={{ width:"100%", padding:13, borderRadius:10, border:"none", background:"#FFD700", color:"#1a1a2e", fontWeight:800, fontSize:16, cursor:"pointer" }}>دخول</button>
        <button onClick={()=>setShowAdminLogin(false)} style={{ width:"100%", padding:11, marginTop:8, borderRadius:10, border:"none", background:"transparent", color:"rgba(255,255,255,0.35)", cursor:"pointer" }}>إلغاء</button>
      </div>
      <Nav />
    </div>
  );

  return (
    <div style={{ background:"linear-gradient(160deg,#0d1b3e 0%,#1a1a2e 100%)", minHeight:"100vh", paddingBottom:70 }}>
      {view==="form"    && <DonorForm onSuccess={refresh} />}
      {view==="display" && <DisplayScreen donations={donations} total={total} confettiKey={confettiKey} appUrl={appUrl} />}
      {view==="admin"   && <AdminPanel donations={donations} onConfirm={confirmDonation} onDelete={deleteDonation} onRefresh={refresh} appUrl={appUrl} loading={loading} />}
      <Nav />
    </div>
  );
}
